package run.halo.starter;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;
import org.springframework.test.web.reactive.server.WebTestClient;
import org.springframework.test.util.ReflectionTestUtils;
import reactor.core.publisher.Mono;
import run.halo.app.extension.*;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
class McpWritePermissionTest {
 @Test void permissionIsExplicitPerAgentAndLegacyCredentialsStayReadOnly(){var client=mock(ReactiveExtensionClient.class);var ref=new AtomicReference<Secret>();when(client.fetch(eq(Secret.class),anyString())).thenAnswer(i->Mono.justOrEmpty(ref.get()));when(client.create(any(Secret.class))).thenAnswer(i->{Secret s=i.getArgument(0);s.getMetadata().setVersion(0L);ref.set(s);return Mono.just(s);});when(client.update(any(Secret.class))).thenAnswer(i->{ref.set(i.getArgument(0));return Mono.just(ref.get());});var cfg=new McpConfigService(client);String legacy=cfg.issueMcpToken().block().get("token");var a=cfg.enrollAgent("A").block();var b=cfg.enrollAgent("B").block();assertFalse(cfg.agentAccess(legacy).block().canWrite());assertFalse(cfg.agentAccess(a.get("token")).block().canWrite());cfg.setAgentWrite(a.get("connectionId"),true).block();assertTrue(cfg.agentAccess(a.get("token")).block().canWrite());assertFalse(cfg.agentAccess(b.get("token")).block().canWrite());assertTrue(cfg.validMcpToken(a.get("token")).block());cfg.setAgentWrite(a.get("connectionId"),false).block();assertFalse(cfg.agentAccess(a.get("token")).block().canWrite());assertThrows(Exception.class,()->cfg.requireWriter(a.get("connectionId")).block());}
 @Test void readonlyTokenCannotCallHiddenWriteToolsAndHasOnlyThreeTools(){var cfg=mock(McpConfigService.class);var settings=new McpSettings();settings.setEnabled(true);when(cfg.settings()).thenReturn(Mono.just(settings));when(cfg.validMcpToken("token")).thenReturn(Mono.just(true));when(cfg.agentAccess("token")).thenReturn(Mono.just(new McpConfigService.AgentAccess("agent-a",false)));var reads=mock(BlogMcpTools.class);when(reads.list()).thenReturn(List.of(Map.of("name","site_info"),Map.of("name","search_articles"),Map.of("name","read_article")));var writes=mock(McpWriteTools.class);when(writes.supports("publish_moment")).thenReturn(true);var endpoint=new McpEndpoint(cfg,new McpAccess(),new OwnerSessions(),reads);ReflectionTestUtils.setField(endpoint,"writes",writes);var api=WebTestClient.bindToRouterFunction(endpoint.endpoint()).build();api.post().uri("/mcp").header("X-Frame-MCP-Token","token").header("MCP-Protocol-Version",McpEndpoint.PROTOCOL).bodyValue(Map.of("jsonrpc","2.0","id",1,"method","tools/list")).exchange().expectBody().jsonPath("$.result.tools.length()").isEqualTo(3);api.post().uri("/mcp").header("X-Frame-MCP-Token","token").header("MCP-Protocol-Version",McpEndpoint.PROTOCOL).bodyValue(Map.of("jsonrpc","2.0","id",2,"method","tools/call","params",Map.of("name","publish_moment","arguments",Map.of()))).exchange().expectBody().jsonPath("$.result.isError").isEqualTo(true);verify(writes,never()).call(any(),any(),any());}
 @Test void multipartRequiresIndependentAgentWriteGrantBeforeReadingBody(){var cfg=mock(McpConfigService.class);var settings=new McpSettings();settings.setEnabled(true);when(cfg.settings()).thenReturn(Mono.just(settings));when(cfg.agentAccess(null)).thenReturn(Mono.just(new McpConfigService.AgentAccess("",false)));when(cfg.agentAccess("readonly")).thenReturn(Mono.just(new McpConfigService.AgentAccess("agent-a",false)));var images=mock(McpImageService.class);var api=WebTestClient.bindToRouterFunction(new McpWriteEndpoint(cfg,images).endpoint()).build();api.post().uri("/mcpimages").exchange().expectStatus().isUnauthorized();api.post().uri("/mcpimages").header("X-Frame-MCP-Token","readonly").exchange().expectStatus().isForbidden();verifyNoInteractions(images);}
}
